INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-adventures-of-robin-hood', 2301, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zrmguvpjumv6hs9ujbsw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wvkaokqlwbgyxo17zbyn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Adventures of Robin Hood', 'In Robin Hood you must perform many heroic deeds to change the public impression of you from "villain" to "hero."  The protagonist, Robin of Loxley, is robbed of his castle by the Sheriff of Nottingham and has to get it back with the help of Maid Marian, Little John, Will Scarlet and Friar Tuck. This involves bringing together your band, perform many heroic deeds to change the public impression of you from "villain" to "hero" - heroic acts increase Robin''s popularity among NPC - and killing the Sheriff and his guards.  The gameplay can be described as an action RPG. The player controls Robin as he robs from the rich to give to the poor, adventures through Sherwood Forest, defeats the sheriff''s henchmen, saves peasants and gathers special objects.  There are around 6 extra items you can find in the game, most of which aren''t essential but make the game a lot easier.  Archery plays an important role in gameplay.  The isometric interface developed for The Adventures of Robin Hood by Millennium Interactive is similar to the interface used in Populous. Robin Hood''s interface was later used for Rome: Pathway to Power by Millennium Interactive.' FROM games WHERE igdb_id = 2301 ON CONFLICT (game_id, language_code) DO NOTHING;
