INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('aquales', 45380, '1991-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6x2y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6a2b.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquales', 'In the year 2069, the British ship "Elias Rits" sailed to Kermadec Island on a private investigation mission. Shortly thereafter, satellites reported that beacon transmissions from the ship have stopped. Seeing that further investigation required exploration of hostile environment and deep sea, the authorities dispatched a special team known as W-ODL to find out what has happened to the ship. Navigating a powerful mecha, the American pilot Fredric von Nyuya has to get to the bottom of the mystery and report his findings to the crew. Aquales is an action platformer. The mecha is equipped with a default fist-like melee weapon and gains access to other methods of destruction later, including chainguns, rockets, homing missiles, and more exotic items such as a gravity flamethrower. The stages usually consist of series of platforms and are fairly large, with optional areas and power-ups (health, one-time attacks, etc.) in treasure chests. The protagonist''s stand-out equipment is the grappling hook, which must be used frequently to access high platforms. The game also has a light RPG angle: the hero gains experience points from defeating enemies and levels up as a result. Each stage ends with a boss battle, after which the player''s progress is saved.' FROM games WHERE igdb_id = 45380 ON CONFLICT (game_id, language_code) DO NOTHING;
