INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Space', '''King of Space'' is a hypertext-based game in a science-fiction setting. The work was published in 1991 and remains one of a handful of e-lit works that tackle the science fiction genre. A dark science-fictional ritual of fertility and regeneration, ''King of Space'' takes place in an abandoned starship, circling the edges of a plague-ridden and collapsing solar system, where an escaped terrorist meets the last star-captain and his ship''s Priestess. Old man and young, young woman and ageless starship meet and meet again as enemies, allies, rapists, and lovers.' FROM games WHERE igdb_id = 345268 ON CONFLICT (game_id, language_code) DO NOTHING;
