INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Isolated Warrior', 'They''re coming to your town! Isolated Warrior is a high-speed, uniquely developed game based on a 3-D concept that features over 40 types of enemy creatures, realistic graphics and explosive sound effects! Become Max Maverick, a lone warrior, who must defeat the awesome creatures that attack his highly civilized planet!' FROM games WHERE igdb_id = 48154 ON CONFLICT (game_id, language_code) DO NOTHING;
