INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Profezia', 'Profezia (Italian for "prophecy") is an adventure game with a multiple-choice interface and a medieval theme. Whenever an action is to be taken, the player is presented with a set of choices, which will affect the rest of the adventure.' FROM games WHERE igdb_id = 80986 ON CONFLICT (game_id, language_code) DO NOTHING;
