INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z II: Gekishin Frieza!!', 'Dragon Ball Z II: Gekishin Frieza!! is a role playing video game released only in Japan by Bandai on August 10, 1991, for the Nintendo Famicom. Gekishin Freeza!! is also one of the games downloadable in the game compilation J Legend Retsuden for Nintendo 3DS.' FROM games WHERE igdb_id = 48682 ON CONFLICT (game_id, language_code) DO NOTHING;
