INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CJ Elephant Fugitive', 'Accused of a crime he did not commit - CJ Elephant is imprisoned in a Zoo. Using advanced peanut propelling weaponry, an uncanny ability to find explosive charges and a handy umbrella he promptly escapes.  Now he must flee London, push on to Paris, across the Alps and career through Cairo until he finally makes it home to Africa.' FROM games WHERE igdb_id = 46303 ON CONFLICT (game_id, language_code) DO NOTHING;
