INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bells & Whistles', 'Detana!! TwinBee is a vertically scrolling shoot ''em up game following the same conventions established in the original TwinBee, where players assume the role of Light and Pastel taking control of TwinBee and WinBee across seven levels to defeat invading forces of the evil alien Iva and save planet Meru. It was later re-released on PlayStation and Saturn as part of Detana TwinBee Yahho! Deluxe Pack, PlayStation Portable as part of TwinBee Portable, and Xbox 360 and PC through Game Room service.' FROM games WHERE igdb_id = 39878 ON CONFLICT (game_id, language_code) DO NOTHING;
