INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WWF Wrestlemania', 'WWF WrestleMania is a wrestling game based on the World Wrestling Federation license. It features five wrestlers: Hulk Hogan, André the Giant, “Macho Man” Randy Savage, “The Million Dollar Man” Ted DiBiase, and Bam Bam Bigelow. Players compete in one-on-one matches, aiming to drain the opponent’s energy bar to win.' FROM games WHERE igdb_id = 366703 ON CONFLICT (game_id, language_code) DO NOTHING;
