INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tenchi-wo-kurau-ii-shokatsu-koumei-den', 48346, '1991-04-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co539w.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tenchi wo Kurau II: Shokatsu Koumei-den', 'A Japanese roleplaying game published for the NES in 1991. Based on the manga Tenchi wo Kurau. Tenchi o Kurau II: Shokatsu Koumei-den ("The Devouring of Heaven and Earth II: The Story of King Ming") is a turn based roleplaying and strategy game developed and published for the Nintendo Entertainment System by Capcom on April 5th, 1991 in Japan. It is the second NES RPG produced by Capcom based upon the Tenchi wo Kurau manga series, the first being Destiny of an Emperor released in 1989. Gameplay: A traditional Japanese roleplaying game at its core, Tenchi o Kurai II puts the player in control of a party of warriors and mages as they try to take down a great foe that threatens the peace of their land. Throughout there are random encounters, boss battles, an experience system and valuable and/or useful loot. The player''s party can hold up to seven members at a time, with one members acting as a "tactician". The tactician determines the list of tactics available for use by the player during battle.' FROM games WHERE igdb_id = 48346 ON CONFLICT (game_id, language_code) DO NOTHING;
