INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('taiheiki', 4397, '1991-12-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a3v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceypn.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiheiki', 'Taiheiki is a turn-based strategy game, based on the television drama of the same name, which in turn is based on a famous 14th-century historical epic which chronicles the fall of the Hōjō clan during the Kamakura period of Japanese history. The game is a grid-based strategy game in the tradition of Fire Emblem or Langrisser. Each side has multiple units, which can move depending upon the terrain. Conflicts between units are shown as animated sequences, and the player can determine formations, as well as issue and change orders to different troops at any time. Battles between enemy commanders take the form of a side-scrolling 1-on-1 action sword battle. There are two scenarios available. The first casts the player as Takauji Ashikaga as he attempts to oust Godaigo and establish a new government, while the second follows Masashige Kusunoki and Yoshisada Nitta, who must try to protect Emperor Godaigo and his imperial rule. The two scenarios intertwine at various points, and graphical story sequences between each battle drive the story.' FROM games WHERE igdb_id = 4397 ON CONFLICT (game_id, language_code) DO NOTHING;
