INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leander', 'Leander is a computer game for the Commodore Amiga developed by Traveller''s Tales and published by Psygnosis in 1991. It was the first game to be developed by Traveller''s Tales. The original version was developed on the Amiga, then it was converted by Philipp Wyatt for W.J.S Design on the Atari ST. A year later it was ported to the Sega Mega Drive as The Legend of Galahad and published by Electronics Arts.' FROM games WHERE igdb_id = 12173 ON CONFLICT (game_id, language_code) DO NOTHING;
