INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyper Marbles', 'Hyper Marbles is an action game for the Sega Mega Drive, released exclusively in Japan via the Sega Game Toshokan service. The object of Hyper Marbles is to knock all of your opponents into the electrical fences at the sides of the stage, while making sure you aren''t knocked in yourself. A, B and C boosts.' FROM games WHERE igdb_id = 45728 ON CONFLICT (game_id, language_code) DO NOTHING;
