INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Les Manley in: Lost in L.A.', 'Continue the adventure of Les Manley in this sequel. Using a new mouse interface, lead Les on an adventure through L.A. to find his missing friend, Helmut. Someone is kidnapping the hippest stars in Hollywood. Les Manley must scour La La Land – sifting through out-of-work actors, rock stars and gorgeous babes – to unravel the mystery in this point and click adventure.' FROM games WHERE igdb_id = 72090 ON CONFLICT (game_id, language_code) DO NOTHING;
