INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Sbaitso', 'Less of a traditional game and more of a cross between a benchmark tool and a time waster, Dr. Sbaitso was a talking artificial AI program that came with early Sound Blaster cards. He posed as a psychiatrist, but many of the answers Sbaitso gave the player were rambling and nonsensical.' FROM games WHERE igdb_id = 64002 ON CONFLICT (game_id, language_code) DO NOTHING;
