INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castles', 'Welcome to the world of Castles. As a lord or lady of the realm, you''ve built the castle of your dreams, battled bloodthirsty dragons, engaged in brutal treachery, sent troops abroad to war, and defended your land against marauding enemies. But they''re still not happy. Maybe you shouldnt have poured hot oil on their heads...?' FROM games WHERE igdb_id = 11267 ON CONFLICT (game_id, language_code) DO NOTHING;
