INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CJ''s Elephant Antics', 'CJ''s Elephant Antics is a platform video game developed by Genesis for the Commodore 64 with conversions made for the Commodore Amiga, Atari ST, ZX Spectrum and Nintendo Entertainment System. All ports were handled by Genesis with the exception of the ZX Spectrum version which was handled by Big Red Software. The computer versions were published by Codemasters in 1991. with the NES game arriving in 1992 as part of the unlicensed compilation cartridge Quattro Arcade. The player controls a baby elephant by the name of Columbus Jumbo on his way home to Africa.' FROM games WHERE igdb_id = 12007 ON CONFLICT (game_id, language_code) DO NOTHING;
