INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Kings: The Early Years', 'Experience the majestic birth and childhood of Christ as you proclaim His honor and endevor to experience the prophecies. Collect gifts for Baby Jesus; escape to Egypt to avoid the wrath of King Herod; and search for young Jesus in the holy city of Jerusalem. Test your Bible skills by answering scores of Bible questions designed to compliment the game play.' FROM games WHERE igdb_id = 48148 ON CONFLICT (game_id, language_code) DO NOTHING;
