INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cave Noire', 'Cave Noire is a roguelike video game revolving around four quests: killing monsters, freeing fairies, or collecting gold/orbs with ten difficulties each. Starting a quest creates a randomly generated dungeon where the player has one chance to reach the goal – death means a new dungeon has to be created. The difficulty determines how big the target number is, the stats the player starts with, and what monsters are encountered.' FROM games WHERE igdb_id = 49076 ON CONFLICT (game_id, language_code) DO NOTHING;
