INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-ninja-boy', 42603, '1991-12-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4woq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1te9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Ninja Boy', 'Super Ninja Boy is an action RPG for one or two players. In a two player game, each player controls either Jack or Ryu. In a one player game, only Jack appears. A second player may join at any time by visiting a convenience store. The game contains familiar role-playing elements such as equipping differing kinds of weapons, equipment and gaining levels. The Ninja Boys are treated as a single entity and so these statistics are shared between Jack and Ryu with equal values. Battles with the enemy, either through random encounters or visible on the map is where the action starts. The characters enter a side-scrolling ''battle mode'' where they may jump, fight, use their special techniques, items and spells, as well as activate various bonuses on the battlefield by breaking open the bonus boxes. A battle is over and experience points awarded when a pre-determined number of enemies are defeated or the Ninja Boys are defeated. When bosses are encountered, the gameplay changes to a turn-based system. Each turn, commands are given to Jack and Ryu, which include usage of special items and skills acquired during the game, who then perform actions based on those commands. The enemy''s turn takes place the same way. The battle ends when one side of the conflict runs out of hitpoints.' FROM games WHERE igdb_id = 42603 ON CONFLICT (game_id, language_code) DO NOTHING;
