INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('laser-invasion', 48145, '1991-04-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o2l.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laser Invasion', 'A summer offensive in the year 1999. Never in your military career have you been in such a hot spot, as the world''s most threatening power, Sheik Toxic Moron, deploys his arsenal of TechnoScorch Weapons. To achieve total victory over 4 intense levels, you must possess numerous skills, including precision reflexes for air combat, a cut throat mentality for land assaults, the brains to gather secrets from underground informants, and a keen sense for surviving 3-D battle mazes. If you''ve got the guts to match those skills, then prepare for action. Because it''ll really heat up the second you blast across the Sheik''s firing line, piloting the world''s most advanced super weapon - the Mach 4 Laser Invasion Helijet, which can go from hovering to a six "G" vertical climb in a heartbeat. From the moment you activate your Vulcan Cannons and Sidewinder Missiles, you''ll take dead aim on an insane assault, featuring Anti-Copter Rocket Launchers, High-Altitude Bombers and Aerial Mines. But the battle''s just begun, and there''s no time to kill between firefights!' FROM games WHERE igdb_id = 48145 ON CONFLICT (game_id, language_code) DO NOTHING;
