INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jimmy-connors-pro-tennis-tour', 42605, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21hh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru11.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jimmy Connors Pro Tennis Tour', 'Using crosshairs, aim your ball to the other side of the court and hope you hit where you want. If you are lucky, you might even score an Ace. If not, you will need to be ready to return your opponent''s return. Run back and forth as you try to keep hitting the ball over the net until your opponent misses, or you do. When you hit the ball, you will want to attempt changing the direction and speed of the ball to throw your opponent off balance. This is the real challenge of any tennis game. The title was released as "Great Courts 2" in France and Germany, while the rest of Europe saw it released as "Pro Tennis Tour 2". An Atari Jaguar port was announced in November 1993, but was never released for unknown reasons.' FROM games WHERE igdb_id = 42605 ON CONFLICT (game_id, language_code) DO NOTHING;
