INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-ace-ii-borfs-revenge', 50265, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xpl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdye.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Ace II: Borf''s Revenge', 'Another Laserdisc conversion of one of Don Bluth’s cartoons: Space Ace II: Borf’s Revenge continues the saga of young cadet Dexter, who tries to free his love Kimberly from the clutches of the evil nemesis Borf. In critical situations, the meek Dexter can transform into his mighty alter ego Space Ace. Thus empowered, he has to defeat Borf’s minions. Space Ace II is a essentially a cartoon strip in which our hero will encounter numerous hazards. You have to avoid traps and enemies by pressing the right key at the right time: cursor keys for movements, Insert key to shoot. You never control Dexter directly, you just choose an appropriate direction. Each of the 27 seconds-long scenes requires one to three keystrokes. If your decision is wrong, the cartoon will end with a death animation, and Dexter will lose one of his three lives. So you’re basically trying to keep the strip running. Timing is crucial; you will need to press keys in the exact second. Luckily, you’re allowed to save your progress at four fixed points. Space Ace II is ported to the PC from the original arcade Laserdisc version. The result is a cut version due to space restraints. Although Space Ace II comes on 12(!) low density 5 1/4" discs, most scenes are shortened noticeably.' FROM games WHERE igdb_id = 50265 ON CONFLICT (game_id, language_code) DO NOTHING;
