INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Desperado 2', 'In Desperado 2, the sequel to Desperado, the player is Marshall James, a sheriff sent by the state of Texas to restore order in the corrupt and violent town of Devil Stone. The game is divided into two parts. In the first one it is a side scrolling shooting game. In the second part, located in the typical western saloon, it is a first-time shooter. person.' FROM games WHERE igdb_id = 13590 ON CONFLICT (game_id, language_code) DO NOTHING;
