INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyperspeed', 'There''s no room for error when travelling at the speed of light, racing through star systems in a desperate search for a new world to house Mankind. But there are plenty of opportunities for mistakes. Alien races of every conceivable size, shape, temperament and sophistication seek to aid, use, corrupt or destroy you - and you don''t know which.' FROM games WHERE igdb_id = 35801 ON CONFLICT (game_id, language_code) DO NOTHING;
