INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganbare Goemon: Yukihime Kyuushutsu Emaki', 'Ganbare Goemon: Yukihime Kyuushutsu Emaki is is a light-hearted action-adventure game for 1-2 players and the first game in the Ganbare Goemon series for the Super Famicom. It was later released in the Western market as The Legend of the Mystical Ninja with several changes.' FROM games WHERE igdb_id = 371833 ON CONFLICT (game_id, language_code) DO NOTHING;
