INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Free D.C!', 'Free D.C! is primarily an adventure game, in which conversations with other characters provide most of the clues. The game is not puzzle-oriented in the way contemporaries such as Monkey Island and Legend of Kyrandia are, and is organized in a non-linear way. Graphics are made using Claymation figures, and the sound includes sampled speech.' FROM games WHERE igdb_id = 80526 ON CONFLICT (game_id, language_code) DO NOTHING;
