INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Das Boot: German U-Boat Simulation', 'A German submarine simulator partially inspired by the Das Boot movie. The game contains several missions for your submarine, which must be accomplished. There are several battle stations like : torpedo bay, anti aircraft gun, navigation, etc... which must be mastered to succeed.' FROM games WHERE igdb_id = 14332 ON CONFLICT (game_id, language_code) DO NOTHING;
