INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('500-cc-motomanager', 14196, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co91dg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/epvzkra0hfcrcyyucfcu.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '500 c.c MotoManager', 'In this immersive 500cc motorcycling management simulation, players start with a $4 million budget to build their dream team. The game seamlessly blends economic strategy, technical management, and racing action across renowned circuits like Phillip Island. Players select from 20 international racers and 14 high-performance motorcycles from top manufacturers, balancing rider skills and bike specifications to create a winning combination. As the season progresses, players transition from novice racers to seasoned professionals. The gameplay alternates between hands-on racing simulation—where players control acceleration, gear shifts, and cornering—and strategic team management, where they guide their rider through real-time race conditions. With both single-track and championship modes available, the game offers engaging experiences for solo players or turn-based competition for two, allowing motorsport enthusiasts to test their skills both on and off the track.' FROM games WHERE igdb_id = 14196 ON CONFLICT (game_id, language_code) DO NOTHING;
