INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asmik-kun Land', 'Recently, monsters began to invade the peaceful country of the dragons. The only way to stop this invasion is to contact the six Dragon Gods. Unfortunately, those gods seem to be asleep. Asmik-kun must travel all over the world to find six magical splitters, that will help him to awaken the dragons and to defeat the monsters.' FROM games WHERE igdb_id = 48616 ON CONFLICT (game_id, language_code) DO NOTHING;
