INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Teenage Mutant Ninja Turtles 3: Shredder''s Last Stand', 'Teenage Mutant Ninja Turtles 3: Shredder''s Last Stand is a stand-alone handheld video game by Konami, released in 1991. It is based off the 1987 TV series. This game was adapted for a Japan-exclusive 1994 release under the title of "Teenage Mutant Ninja Turtles LSI Game & Electrical Note."' FROM games WHERE igdb_id = 218930 ON CONFLICT (game_id, language_code) DO NOTHING;
