INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chuck-yeagers-air-combat', 51396, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nk2epaxvzjxppdj2u5kt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdxs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chuck Yeager''s Air Combat', '50 accurate historic missions. Become an ace in one day like Yeager in World War II, fight Sabres high over the Yalu River in Korea, fly in the biggest air battle of Vietnam. Korean War. Jet aircraft dominate the skies. Tactical updates on call. You have a Sabre in your sights, but is he alone? Info windows give you critical data on enemy locations, plane performance, even your opponent''s next move. Missiles make their first deadly mark. Accurate flight dynamics. Faster speeds and greater Gs put your pilot skills to the test. Gunning fighters over Germany was hard, but a missile lock at Mach 1 is a whole different ballgame.' FROM games WHERE igdb_id = 51396 ON CONFLICT (game_id, language_code) DO NOTHING;
