INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battle-dodgeball-toukyuu-daigekitotsu', 49148, '1991-07-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3c40.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ksx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Dodgeball: Toukyuu Daigekitotsu!', 'Battle Dodge Ball is a part of the Japanese exclusive Compati Hero Series. Gundam, Kamen Rider V3, and Ultraman Taro are the main representatives of the ''heroes'' side of the six teams in Battle Dodge Ball, with Zeong, Ika Devil, and Zetton rounding out as the villains. The general gist of the game is that you can choose one of the six teams. You then fight each of the other five teams once per round in a short dodgeball game, two-on-two. Unlike normal dodgeball, you are not knocked out with a single hit. Rather, in Battle Dodge Ball, each character has a specific amount of HP. Once he takes enough hits to lose all his HP, he is out of the match. The game also adds an RPG element in the ability to gain experience at the end of a match, win or lose, which can then be used to power up stats of your team''s players.' FROM games WHERE igdb_id = 49148 ON CONFLICT (game_id, language_code) DO NOTHING;
