INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barney-bear-goes-to-school', 12399, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tjm18ctkmo7kz9uzorlf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ipafa4qnisagv50uzst3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barney Bear Goes to School', 'It''s the first day of school for Barney Bear! Barney Bear Goes To School is a colorful, musical game for children ages 3-8. Barney Bear begins on the morning of the first day of school. The player must help Barney wake up, get dressed, eat breakfast and make his way to school. Once through this short, interactive story, Barney enters the school room. Here, the room itself is a menu of activities and games for a child. There are the numbers and counting games, the alphabet and letter games, colors, shapes, toys, and objects all with accompanying sounds and descriptions.  There is also a painting easel that allows children to fill-in the colors over a dozen different pictures. This delightful game allows even very young children to play without any adult supervision.' FROM games WHERE igdb_id = 12399 ON CONFLICT (game_id, language_code) DO NOTHING;
