INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hoyle-official-book-of-games-volume-3', 50273, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co63d8.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoyle Official Book of Games: Volume 3', 'Six board games are transformed to the computer screen in the third Hoyle''s release. Snakes & Ladders, Backgammon, Yacht / Yahtzee, Checkers, Dominoes and Pachisi / Parcheesi all feature, with animated graphics and sound effects. As there is no time-sensitive action, and the game rules are familiar, these packs were designed to appeal to a wider range of people than most computer games. At least one human player is required - other players can be human or computer. The 18 computer opponents from the first Hoyle''s game return, many of them modeled on other Sierra characters such as Larry Laffer, and again some play ''good'' and some play ''evil''.' FROM games WHERE igdb_id = 50273 ON CONFLICT (game_id, language_code) DO NOTHING;
