INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Booly', 'Booly is a puzzle game with a similar concept to Gem’X in some ways. You are presented with a top-down view of an array of inter-connected blocks, which are shown in a variety of colours. The aim is to turn them all to grey, but clicking on them will often cause a pattern of other squares to change to the next colour in the sequence as well.' FROM games WHERE igdb_id = 12406 ON CONFLICT (game_id, language_code) DO NOTHING;
