INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waku-waku Sonic Patrol Car', 'Waku Waku Sonic Patrol Car is a children ride released on December 1991 exclusively in Japan. The arcade ride is part of Sega''s "Wakuwaku" line and features Sonic the Hedgehog playing the role of a police officer, patrolling the streets of a city and keeping it safe from Dr. Eggman. Both Japanese and English versions of the ride exists, though the English version was not exported to other countries and was likely used in areas with a large number of visiting English speaking tourists.' FROM games WHERE igdb_id = 39461 ON CONFLICT (game_id, language_code) DO NOTHING;
