INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solvalou', 'Solvalou is a 1991 first-person rail shooter arcade game developed and published in Japan by Namco. The sixth entry in the Xevious series, the player takes control of the Solvalou starship from a first-person perspective as it must destroy the Xevious forces before they take control of Earth. The Solvalou has two weapon types: an air zapper to destroy air-based enemies, and a blaster bomb to destroy ground-stationed enemies. It runs on the Namco System 21 arcade board.' FROM games WHERE igdb_id = 39805 ON CONFLICT (game_id, language_code) DO NOTHING;
