INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bubblegum-crash', 43201, '1991-12-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xcw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpehi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubblegum Crash', 'Bubblegum Crash is a PC Engine graphic adventure game based on the anime OVA series of the same name. The anime/game is set in the near future of 2032, which has seen Tokyo split into two by a massive earthquake. Corporations rule the country, production-line humanoid robots named "boomers" are being used by villains to commit crimes, and the beleaguered police are too under-budgeted and incompetent to handle it all. The all-female mercenary team the Knight Sabers, who use powerful exosuits called "Hard Suits", are the city''s best defense. The game operates similarly to other adventure games of the era. The player is given a selection of commands that they can use to interact with the world, including talking to NPCs, picking up and using objects in their inventory and moving to other areas. At any time the player can look and listen for extra context clues. The commands are in English, but the game''s story and dialogue text is entirely Japanese. The game will occasionally switch protagonists, starting with Nene Romanova and moving to Priss, Linna and Sylia at various points.' FROM games WHERE igdb_id = 43201 ON CONFLICT (game_id, language_code) DO NOTHING;
