INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elle', 'Elle is a point-and-click adventure in Japanese style (no puzzles). The interaction with the environment is performed by moving the mouse cursor around; when it is possible to interact with an object, the cursor turns into a command icon (look, talk, push, take, etc., depending on the situation). The navigation is performed by selecting locations from a menu. The player advances by examining objects, talking to people, and unlocking new locations.' FROM games WHERE igdb_id = 171973 ON CONFLICT (game_id, language_code) DO NOTHING;
