INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Taluluto-kun: Fantastic World!!', 'Fifth grader Edojou Honmaru is one of the most trodden-upon losers in his class, until he meets Magical Taluluto-kun. Taluluto''s powers help him deal with all his hardships, such as girls, bullies, and numerous other challenges.' FROM games WHERE igdb_id = 48433 ON CONFLICT (game_id, language_code) DO NOTHING;
