INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Blue Marlin', 'The Blue Marlin was developed by Hot B in 1991 for the Nintendo Entertainment System. Following their earlier release The Black Bass, Hot B built on some of the original features for this fishing game. With the abilty to gradually increase attributes in muscle power, body strength, and skill; the player has more control over how the game is played compared to Black Bass.' FROM games WHERE igdb_id = 48104 ON CONFLICT (game_id, language_code) DO NOTHING;
