INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu Koukou Dodgeball-bu: CD Soccer-hen', 'While Kunio and Shinichi were practicing dodge ball, soccer manager Misako approached the two on the court. "Please! Instead of dodgeball, join me and play soccer in the national convention!" Nekketsu High Soccer Club has come down with food poisoning, and Kunio must lead his dodgeball team into the soccer competition and go for the goal! Only through winning the championship can Kunio convince his whole team to join him. Nekketsu Koukou Dodgeball Bu: CD Soccer Hen presents the classic soccer game with crystal clear sound and high resolution graphics like never before seen in the series!' FROM games WHERE igdb_id = 44305 ON CONFLICT (game_id, language_code) DO NOTHING;
