INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fgodmom', 85946, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co63dh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scfeta.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F.Godmom', 'F.Godmom is a platform game, featuring a fairy godmother as the protagonist. All the fairy godmothers have been captured, and only you are left to save them. On each level, the player needs to collect all the tokens, find the key and get to the exit. Monsters kill the fairy if they come in contact with her. The player''s only weapon is a magic wand that can be used to transform objects. The player first uses the wand on any object to acquire a "wand pattern", then he can transform anything (walls, ladders, monsters...) into said object. This can be used to create ladders to travel, get rid of monsters etc., though all transformed objects revert to their original form after a while. Some levels feature gray objects which cannot be affected by the wand.' FROM games WHERE igdb_id = 85946 ON CONFLICT (game_id, language_code) DO NOTHING;
