INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kero-kero-keroppi-no-daibouken', 48351, '1991-04-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/y1ymgzrdylqow7anrwxd.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kero Kero Keroppi no Daibouken', 'Kero Kero Keroppi no Daibouken is based on the popular Sanrio character Keroppi. Released on the Nintendo Family Computer console in Japan in 1991. Big Adventure is a children''s puzzle game where Keroppi must rescue his girlfriend Keroleen who is locked up in a castle. To do so, he must solve the action based puzzles in seven differently themed worlds with four different types of stages (the surface of the maze, flying a plane, a Reversi-like level, and through a field of lava). All the items in the game are pre-determined; there is a need to memorize the pattern for each playthrough so that a player may advance through the levels more quickly once they have achieved a degree of expertise in the game.' FROM games WHERE igdb_id = 48351 ON CONFLICT (game_id, language_code) DO NOTHING;
