INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zona-0', 45374, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4pdz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mxicrizuqr76mbtsoaq8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zona 0', 'Zone 0 is an arcade-type video game made by the Spanish video game company Topo Soft in 1991 for the 8-bit Sinclair ZX Spectrum, MSX, Amstrad CPC computers and for the 16-bit PC. The video game is based on the 1982 Walt Disney film TRON, in the scene of the fight on light motorcycles, where the player must make the other participants collide with his wake so that he is the only survivor. Technically, the game hints at the beginning of the end of the golden age of Spanish software, since the program was made with very few means, although the result was very successful. Created in isometric perspective and with a relatively smooth scroll. The game was tried to be officially supported by the original movie license, but in the end it was not possible' FROM games WHERE igdb_id = 45374 ON CONFLICT (game_id, language_code) DO NOTHING;
