INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robbie and the Robots', 'Robbie Robot is the fifty first game of the NES version of Action 52. You play as Robbie as you are shooting other robots with guns or finger missiles and try not to have the enemies shoot you, because if they do, you die. At the first level, the player can just constantly go straight ahead, constantly shooting. But at the next levels, gaps appear, so the passage becomes much more difficult.' FROM games WHERE igdb_id = 245111 ON CONFLICT (game_id, language_code) DO NOTHING;
