INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rules of Engagement', 'Rules of Engagement is a role-playing game in which you take on the role of a Fleet Commander deployed to lead Federated Worlds forces in specific missions against enemy or rebel forces. Each mission takes place an a particular solar system. The game is very realistic and extremely difficult. The extensive manual as attached to help the new players to become familiar with the game mechanics.' FROM games WHERE igdb_id = 14421 ON CONFLICT (game_id, language_code) DO NOTHING;
