INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rattler-race', 78811, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7miu.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rattler Race', 'Very much a snake game, Rattler Race adds a few twists to the long-held conventions of the genre (those being: you guide a snake from a top-down perspective, always in forward motion; it eats its targets and grows in length, but dies should it collide with any obstacles): in addition to a competing snake foiling your routes, a ball bounces around the play-field, Pong-style, killing your snake should the ball ricochet against its head. The other standout qualities are largely cosmetic: periodically enemy movement "freezes", giving the player a period of free motion; the opposing snake will also "eat" your targets (here "apples" -- occasionally bonus "golden apples") and grow longer, though it doesn''t seek them out; gameplay can be conducted with as many as three opposing snakes and three bouncing balls complicating the playfield at once; you head for the exit once all apples are eaten, but the enemy snake(s) can exit instead, restarting the level. Triumph against all these odds and you get 29 more levels of similar gameplay! This unremarkable clone is largely known on account of having been included in the second "Microsoft Entertainment Pack" for Windows.' FROM games WHERE igdb_id = 78811 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 78811 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 78811 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-max-aces-of-the-great-war', 11972, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co63dl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar19dj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Max: Aces of the Great War', '1914- the peaceful, blue skies over France are shattered forever by the machine guns of mankind''s first fighting aircraft. The medal "Pour le merite"- the British called it "the Blue Max"- was awarded to the best German pilots of World War I. To flyers of both sides it symbolized the utmost in daring, courage and honor during a time that will never be repeated in the story of aviation. Fame was rated daily on the numbers of planes shot down; rapid advances were made in flying technology and techniques; men prepared them selves to die at the word of a leader. And out of it all grew the desire to fly and win that pushed pilots, airplanes, and the newborn aviation industry to the limits. In Blue Max, Aces of the Great War, begin by choosing sides and one of eight fighters. Action is immediate and relentless, as you fly the most famous aircraft of the time- Fokker, Spad, Nieuport, Sopwith, Albatros- with the best of the best, including Richthofen, Fonck, Mannock, and Rickenbacker. Learn the characteristics of each plane, and the different tricks and techniques of each ace. Different playing modes let one or two players fly solo, as a team, or against each other using the same computer. Fly in full-action dogfights, undertake missions to destroy bridges and observation balloons, or work out strategies one segment at a time in detail.' FROM games WHERE igdb_id = 11972 ON CONFLICT (game_id, language_code) DO NOTHING;
