INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Fighters 2', 'Punch and kick game from Konami. There are a variety of bad guys for you to stomp and you can even kick them while they are still down on the ground. The occasional boss thug provides an extra challenge. Konami, the Crime Fighters 2 maker, released 359 different machines in our database under this trade name, starting in 1978. Other machines made by Konami during the time period Crime Fighters 2 was produced include Bells & Whistles, Detana!! Twin Bee, Rollergames, Simpsons, The, Sunset Riders, Woo Yah Taa, Trigon, Teenage Mutant Ninja Turtles II: The Arcade Game, Surprise Attack, and Punk Shot.' FROM games WHERE igdb_id = 39526 ON CONFLICT (game_id, language_code) DO NOTHING;
