INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Defense Force', 'A SUPER SAGA OF 23RD CENTURY SATELLITE WARFARE!   The graphics will dozzle you, the speed will astound you... but if you don''t think fast and shoot faster, you won''t have a chance against the alien firestorm. Because in EARTH DEFENSE FORCE, the best defense is always a great offense.' FROM games WHERE igdb_id = 46666 ON CONFLICT (game_id, language_code) DO NOTHING;
