INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-117A Stealth Fighter', 'It''s the F-117A Stealth Fighter. And once you fly it, you''ll see why no other flight simulator compares! Incredible 3-D graphics will keep you glued to your screen as you experience the same intense pressures that gripped America''s Gulf War pilots. Penetrate enemy airspace without being seen! Tangle with the enemy in treacherous dogfights! Launch awesome firepower against fierce opponents! Your wait is over. The ultimate weapon has arrived. Now it''s your turn to pilot the real Stealth Fighter!' FROM games WHERE igdb_id = 69582 ON CONFLICT (game_id, language_code) DO NOTHING;
