INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Destroyer from Jail', 'The Destroyer from Jail is a Korean arcade game that uses the "belt-scrolling" perspective typical of beat ''em ups. but features gun based combat. Control a convict shooting down a criminal boss and his goons across five levels to gain his freedom.' FROM games WHERE igdb_id = 378377 ON CONFLICT (game_id, language_code) DO NOTHING;
