INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hellcats-over-the-pacific', 71323, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9mw7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvz9t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hellcats Over the Pacific', 'Hellcats Over the Pacific is a flight simulator focusing on the Pacific Theater of World War 2. The player assumes the role of a Grumman F6F Hellcat pilot in both land and carrier-based missions using guns and bombs. Hellcats used a special algorithm that Eric Parker initially programmed on a Sun SPARCstation to speed up the display of graphics on the screen. Hellcats offered amazing 256 colors at a time when 16 colors were the norm and (for the time) insanely smooth and fluid animations. The game was a huge hit on the small Macintosh gaming market, selling more than 50,000 copies. It ranked for years in the "most popular games" sections of magazines like Inside Mac Games and won Macworld magazine''s yearly award for the "Best Simulation Game".' FROM games WHERE igdb_id = 71323 ON CONFLICT (game_id, language_code) DO NOTHING;
