INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Feud', 'Based on the television game show, Family Feud. The player chooses a family of five to play against another family. Players are asked to find the most common answers to various questions asked by the host, so the family can earn points. The family with the most points at the end of the game wins the prize money.' FROM games WHERE igdb_id = 159244 ON CONFLICT (game_id, language_code) DO NOTHING;
