INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakajima Satoru Kanshuu: F1 Grand Prix', 'Nakajima Satoru Kanshuu F1 Grand Prix is a 1991 game by Varie for the Sega Mega Drive in their Nakajima Satoru Kanshuu series of Formula One racing games released exclusively in Japan. The game is a typical overhead 2D racing game. A accelerates, B brakes, Left and Right seers, and Up and Down change gears.' FROM games WHERE igdb_id = 45719 ON CONFLICT (game_id, language_code) DO NOTHING;
