INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slightly Magic', 'Slightly Magic is a platform game not unlike Codemasters'' own Dizzy and Seymour series, but is generally shorter and easier than most other games of that genre. In addition to standard inventory puzzles of Dizzy games, Slightly Magic introduces a magic system that requires multiple objects to be combined in order to achieve effects ranging from frightening the enemies to turning the player into a fish.' FROM games WHERE igdb_id = 97124 ON CONFLICT (game_id, language_code) DO NOTHING;
