INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyramid Magic Special', 'Pyramid Magic Special (ピラミッドマジック特別) is a puzzle-platform game for the Sega Mega Drive, released exclusively in Japan via the Sega Game Toshokan service.  Pyramid Magic Special is essentially a re-tooled version of the original Pyramid Magic, with identical graphics, gameplay and music. The levels are mostly the same also, but generally have more obstacles to make them less straight forward.' FROM games WHERE igdb_id = 4428 ON CONFLICT (game_id, language_code) DO NOTHING;
