INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-game-of-harmony', 117976, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9hfe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Game of Harmony', 'Are you smart? Do you have quick reflexes? You are a single spinning sphere. You face a series of fantastic computer-generated puzzles - 50 of them. Your goal? Knock similar balls together and make them disappear. Sound simple? It''s not. Each puzzle is different and requires a different strategy. Hit the wrong balls together and they multiply. If you don''t clear the screen in time, the whole thing explodes. Whatever you''ve done before, forget it. Harmony''s a whole new ball game. Beat this baby and you can call yourself good. Until then, you''re just a pretender.' FROM games WHERE igdb_id = 117976 ON CONFLICT (game_id, language_code) DO NOTHING;
