INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fidelity Ultimate Chess Challenge', 'This handheld chess game uses Chessmaster 2100''s basic game engine. This includes such items as en passant attacks for pawn, castling, check and checkmate, and draws for various reasons. Move time limits are optional, and the CPU''s thinking time can be specified. If you need a hint, you can press the B button and the computer may or may not give you a hint. You can also play against another human opponent, alternating.' FROM games WHERE igdb_id = 70778 ON CONFLICT (game_id, language_code) DO NOTHING;
