INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angra-I', 'Angra-I is a text-based adventure developed by Renato Degiovani, about a crazy programmer who has put the nuclear reactor at the Angra dos Reis power plant in the process of self-destruction, and now you, the player, need to enter the power plant, find the reactor control terminals, and deactivate the program that is controlling everything. Time is short, and the player cannot waste it by trial and error. You have to think and act in the right direction, or else... Booooom!' FROM games WHERE igdb_id = 215853 ON CONFLICT (game_id, language_code) DO NOTHING;
