INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quiz Daisousa Sen: The Last Count Down', 'Quiz Daisousa Sen: The Last Count Down is a quiz adventure game. Players control either Neo McDonald or Geo Kentucky in their adventures through Quiz City, a place where answering questions gets results. The genre to these questions include movies, history, geography, songs, sports, and entertainment news. Story progression through the games is largely decided through cutscenes and choices given to players, making the experience very similar to a choose-your-own-adventure.' FROM games WHERE igdb_id = 75510 ON CONFLICT (game_id, language_code) DO NOTHING;
