INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Play: 3-D Soccer', 'I Play 3D Soccer is one of the earliest 3D football games. You take control of a single player, viewing the action from right behind his perspective. Signalling for your team-mates to pass you the ball is a key gameplay element - don''t expect to just watch your team win with no contribution from you. When you gain possession (or press the button while not in possession) your player automatically turns to face the goal.' FROM games WHERE igdb_id = 92957 ON CONFLICT (game_id, language_code) DO NOTHING;
