INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solidarność', 'Solidarność is a 1991 Polish strategy computer game developed by P.Z.Karen Co. under the direction of Przemysław Rokita and published by California Dreams. It was created by Polish programmers specifically for an American audience in order to support a Hollywood film about the life of Lech Wałęsa, which was never actualised. Set in Poland in the 1980s, the player takes the role of the leader of an illegal union, and aims to gain more support in 7 regions than the Communists. The player achieves this through speeches, printing leaflets, organizing demonstrations and strikes.' FROM games WHERE igdb_id = 318229 ON CONFLICT (game_id, language_code) DO NOTHING;
