INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paganitzu Part 2: The Silver Dagger', 'Paganitzu is a tile-based, CGA/EGA computer game created by Keith Schuler and published by Apogee Software in October, 1991. It is the sequel to Chagunitzu. The game is a 2D puzzle game comparable to Chip''s Challenge. It requires the player to solve various puzzles to complete the game. Paganitzu was published in three parts. Part 1: "Romancing the Rose", Part 2: "The Silver Dagger" and Part 3: "Jewel of the Yucatan".' FROM games WHERE igdb_id = 50477 ON CONFLICT (game_id, language_code) DO NOTHING;
