INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hana Taaka Daka!', 'Konta the little fox is in trouble - while on a walk with his girlfriend Inari, he "accidentally" broke the magical seal that held the evil tanuki raccoon Jikanda and his minions prisoner. They have abducted Inari and Konta is in great despair. He decides to seek assistance from the gods and ask them for help. A flying Tengu answers to his desperate plea.' FROM games WHERE igdb_id = 38076 ON CONFLICT (game_id, language_code) DO NOTHING;
