INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Die Drachen von Laas', 'Drachen von Laas tells the story of two young friends who are bored with their everyday life in the medieval fantasy world of Laas. They decide to leave their little village and seek adventures. Adventures they find when they are asked to kill two mighty dragons that rampage the area of a far-away city.' FROM games WHERE igdb_id = 70209 ON CONFLICT (game_id, language_code) DO NOTHING;
