INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyramid Magic III', 'Pyramid Magic III (ピラミッドマジックIII) is a puzzle-platform game for the Sega Mega Drive, released exclusively in Japan via the Sega Game Toshokan service. Pyramid Magic III is a "sequel" to Pyramid Magic II, and like Pyramid Magic II offers little more in terms of upgrades other than harder levels.' FROM games WHERE igdb_id = 45750 ON CONFLICT (game_id, language_code) DO NOTHING;
