INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Big Blue Disk #54', 'Big Blue Disk was a monthly DOS disk magazine. It carried various games and applications for DOS as well as reviews and various extras. Some of them were freeware or shareware, or demo versions of commercial programs, but other material was original to the disk magazine. This issue contains: - Dark Designs II: Closing The Gate - Word Ladders - Handy Caps. The remainder of the space is taken up by clip art, articles and a file-searching DOS utility.' FROM games WHERE igdb_id = 135641 ON CONFLICT (game_id, language_code) DO NOTHING;
