INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Verytex', 'Verytex is a shoot-''em-up game released exclusively in Japan. Taking place on the colonized fictional planet of Syracuse in a futuristic sci-fi setting, where its military force initiated a violent coup d''état against the inhabitants for unknown reasons, players take control of the titular space fighter craft in an attempt to overthrow the enemies, protect civilization and discover the true cause for the rebellion.' FROM games WHERE igdb_id = 46162 ON CONFLICT (game_id, language_code) DO NOTHING;
