INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Madden Football ''92', 'This update of the John Madden football series offers several new features over its predecessor: instant replays, different weather conditions, player injuries and the ability to review and overturn pass interference calls. Play modes include Pre-Season, Regular Season, Playoffs and Sudden Death. There are 28 teams plus one All-Madden team.' FROM games WHERE igdb_id = 4588 ON CONFLICT (game_id, language_code) DO NOTHING;
