INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Berlin Wall', 'The Berlin Wall is a platform arcade game. The player takes control of a boy who must use his hammer to break the blocks that form part of the platform levels that form each stage. These holes act as traps for the many patrolling monsters and once one has fallen into a hole, the player may then use the hammer on the monster to make it fall through the hole and down to the platform below - causing it to change into fruit or power-ups, which can then be collected.' FROM games WHERE igdb_id = 39615 ON CONFLICT (game_id, language_code) DO NOTHING;
