INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'KlashBall', 'The Sport Of The Future! Speedball is the action sport of the 21st century. Wearing spiked armour bodywear, helmet and gloves, you''ll go face-to-face with some of the ugliest, meanest goons in the world! Dodge neckbreaking tackles and bone-crushing body slams to pass a solid steel ball towards your opponent''s goal. Hammer your foe enough times and he''ll cry for mercy.' FROM games WHERE igdb_id = 67941 ON CONFLICT (game_id, language_code) DO NOTHING;
