INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amnios', 'Alive and killing! Penetrate the living hell that is Amnios. Counter your comparatively diminutive ship against the merciless might of ten living, breathing planets in an audacious endeavor to rescue imprisoned members of your own persuasion. Pick up indigenous DNA and utilize it to fabricate enhanced weaponry to abet your pestilential quest. Aw, forget the bull! Just get in there and save the world!' FROM games WHERE igdb_id = 14254 ON CONFLICT (game_id, language_code) DO NOTHING;
