INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '123 Talk', 'The object of 123-Talk is to talk to your child, to help teach them how to say numbers, counting, addition, subtraction, and interact with a computer. For children ages 1-4, 123-Talk will teach your child to say the the numbers 1 through 10 and how to find numbers on the keyboard. They will also learn how to sing the 123 song and how to draw with Easy Draw II. The registered version of this game lets you play with the latest version and also include new features.' FROM games WHERE igdb_id = 263186 ON CONFLICT (game_id, language_code) DO NOTHING;
