INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('caesars-world-of-boxing', 45941, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qj7ib5ungvkofujveywy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caesar''s World of Boxing', 'Create a boxer and work his way up the ladder in this FMV-heavy boxing game for the CD-i.  Caesars World of Boxing is a sports fantasy come true. Imagine experiencing Las Vegas heavyweight boxing in the way you have always dreamed of.........but could never afford. The fighters, the managers, the high rollers, the women, the intoxicating night life of Caesars Palace in Las Vegas. Caesars World of Boxing delivers an interactive boxing fantasy that offers all the color and glamour of being backstage at Caesars Palace, home to the likes of Ali, Holmes and Holyfield for some history''s greatest prize fights, only this time..... the crowd has come to see you fight!  As a FIGHTER, the player must pick the right trainers and managers to take him to the top of the heavyweight ranks, defeat his opponents in the ring and deal with the tempting "distractions" of big time professional sports. The player must navigate a demanding world: the right choices lead to the coveted heavyweight championship, and the wrong choices lead to retirement with the rest of the palookas who only dreamt of being contenders.' FROM games WHERE igdb_id = 45941 ON CONFLICT (game_id, language_code) DO NOTHING;
