INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('top-cat-in-beverly-hills-cats', 71415, '1991-03-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8pw7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctp3s.jpg', NOW()) ON CONFLICT DO NOTHING;
