INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carcharodon: White Sharks', 'A horizontal shoot-em-up in the vein of Silkworm; you fly a plane (a ''White Shark'' no less) across various terrains killing baddies. The reason this game stands out the most is its innovative attempt at a weapons system, which allows the player to choose from up to 37 million weapon combinations(!).' FROM games WHERE igdb_id = 12501 ON CONFLICT (game_id, language_code) DO NOTHING;
