INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('final-match-tennis', 42060, '1991-03-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xev.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Match Tennis', 'Final Match Tennis is by far the deepest tennis game in terms of gameplay on the PC Engine. In fact, its play controls are among the most sophisticated in a PC Engine game and in general, in a tennis game (what still counts to this very day). Don''t get fooled by its simple graphics. There is everything in this game that tennis is about. Smashes, stop balls, volleys, back and forehand spins or lobs. At the top of it all, you can play it in every thinkable player combination (training, tournament, 1-4 players). By the way: in addition, its one of the best multiplayer games ever.' FROM games WHERE igdb_id = 42060 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 42060 AND ge.slug = 'sport' ON CONFLICT DO NOTHING;
