INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('splash-lake', 37610, '1991-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/semobye2uu2zsdkskj9c.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Splash Lake', 'Splash Lake is an action-puzzle game for the TurboGrafx-CD and PC Engine CD-ROM. The player is an ostrich named Ozzie and must walk around a grid, pecking at certain lynchpin areas of the ground in order to collapse parts of the level into the ocean. The goal is to remove all enemies by dropping the ground they''re walking on. It is structurally similar to Dig Dug 2. The game has a multiplayer mode, which allows two players to try to outmaneuver and out-think each other.' FROM games WHERE igdb_id = 37610 ON CONFLICT (game_id, language_code) DO NOTHING;
