INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MicroProse Golf', 'MicroProse Golf is a golf video game developed by The Thought Train and published by MicroProse. It was released in 1991 for Amiga and Atari ST. In 1992, an enhanced MS-DOS version, featuring golf instructor David Leadbetter, was released in the United States as David Leadbetter''s Greens and in the United Kingdom as David Leadbetter''s Golf. The game''s variety was praised, and some critics considered it the best golf game available.' FROM games WHERE igdb_id = 194972 ON CONFLICT (game_id, language_code) DO NOTHING;
