INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ambition of caesar', 'Warrior of Rome, also known as Caesar no Yabou (シーザーの野望?, "Ambition of Caesar"), is a real-time strategy video game for the Sega Mega Drive/Genesis. The game is a fictional story about the adventures of Julius Caesar and the Roman army during his reign as general in the year 48 BCE. The game had a sequel, Warrior of Rome II' FROM games WHERE igdb_id = 45577 ON CONFLICT (game_id, language_code) DO NOTHING;
