INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('d-d-crew--1', 109441, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7zw3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc82hz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D. D. Crew', 'D. D. Crew is a 2D arcade beat''em up, similar to Final Fight. Each player (up to four depending arcade cabinet) controls one of four characters: F. F., Buster, King or Gung Ho, who fight against an evil gang. Gameplay is simple: the heroes move from left to right through each level, and try to beat all enemies on screen. They can use some weapons (like knives and grenades). Each stage has also a boss to kill.' FROM games WHERE igdb_id = 109441 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 109441 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
