INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun: Danger Zone', 'Top Gun: Danger Zone is a combat flight game developed by Distinctive Software and published by Konami and released on DOS on 1991. The player has the choice between two aircraft: the F-14 Tomcat and the F-18 Hornet. The games features a total of eight missions. There is also a mode where the player can compete against 12 others pilots to determinate who is the best. This mode is an one-on-one simulated dogfight, and can be either played by the CPU or a second player.' FROM games WHERE igdb_id = 73092 ON CONFLICT (game_id, language_code) DO NOTHING;
