INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infernal House', 'Far away, in the night, a house... Within its walls is what may be the greatest discovery of the century. After investigating a kidnapping case, you find yourself thrown out of town, in this extraordinary home. Its structure shocks you... It seems to contain a great mystery, much more than a simple abduction... It will take a lot of common sense and observation to find out what this hell house seems to be hiding!' FROM games WHERE igdb_id = 174633 ON CONFLICT (game_id, language_code) DO NOTHING;
