INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Saber', 'Dragon Saber is a vertical scrolling shooter arcade game, released by Namco in 1990; it runs on Namco System 2 hardware, and as its complete title suggests, it is the sequel to Dragon Spirit which had been released three years earlier. The sequel to Dragon Spirit follows much in the same vein, with your flying dragon defeating prehistoric monsters over various landscapes. This time round there is a two player mode thrown in for extra appeal.' FROM games WHERE igdb_id = 38097 ON CONFLICT (game_id, language_code) DO NOTHING;
