INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TriPeaks', 'TriPeaks is a patience or solitaire card game that is akin to the solitaire games Golf and Black Hole. The game uses one deck and the object is to clear three peaks made up of cards. It was created by Robert Hogue and popularized as a result of being included in Microsoft Solitaire Collection 3.' FROM games WHERE igdb_id = 282148 ON CONFLICT (game_id, language_code) DO NOTHING;
