INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boston Bomb Club', 'Boston Bomb Club is a steampunk-themed game, in which a few Victorian gentlemen enjoy their past time of explosive puzzle games. The levels are top-down puzzle "maps" in which the player must direct the ignited bombs across the tiles safely to their destination. There are various tiles of various functions, teleporting, blocking etc.' FROM games WHERE igdb_id = 10865 ON CONFLICT (game_id, language_code) DO NOTHING;
