INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nakajima Satoru: F-1 Hero 2', 'Nakajima Satoru F-1 Hero 2 is a 1991 Japan-exclusive Family Computer Formula One video game developed by Human Entertainment and published by Varie. It is the sequel to Nakajima Satoru: F-1 Hero, and is based on the 1991 Formula One season. There are 16 rounds and only four cars to choose from.' FROM games WHERE igdb_id = 48301 ON CONFLICT (game_id, language_code) DO NOTHING;
