INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Evil', 'Star Evil is the second game of NES version of Action 52. It''s the first game on the cartridge that has a space theme, which is a common theme in the list of games. A lot of these share the same code for the boss and the way you play the game.' FROM games WHERE igdb_id = 243936 ON CONFLICT (game_id, language_code) DO NOTHING;
