INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quiz Meitantei Neo & Geo: Quiz Daisousasen Part 2', 'Quiz Meitantei Neo & Geo: Quiz Daisousasen Part 2 is a quiz adventure game released for the Neo Geo in Japan only. It is a direct sequel to Quiz Daisousa Sen: The Last Count Down released the year prior. Players once again take control over the detectives Neo McDonald or Geo Kentucky, who must explore the city and interrogate people.' FROM games WHERE igdb_id = 75511 ON CONFLICT (game_id, language_code) DO NOTHING;
