INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sex Olympics', 'Sex Olympics has controls comparable to other point-and-click adventures such as the ability to move up, down, left and right, which are context-sensitive to the player''s location, as well as commands to take, drop, touch, give, use, go, look, and talk to NPCs. Sex Olympics also has more ''obscene'' inputs.' FROM games WHERE igdb_id = 289398 ON CONFLICT (game_id, language_code) DO NOTHING;
