INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('clocks', 41369, '1991-04-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vssqbee5vujvnocxwygw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clocks', 'The fourth game featured as a coverdisk on the Japanese magazine Famimaga, Clocks is a Tetris variant in which clock faces must be placed together form larger shapes. Clocks, or Famimaga Disk Vol. 4 Clocks (and occasionally as "Clox"), is a falling blocks puzzle game that is superficially similar to Tetris or Columns. Single clock faces depicting one of four angles fall from the top and the player needs to manipulate and place them so they can form larger objects, such as simple formations like squares, diamonds and hourglass shapes to more object-intensive shapes like octagons and hexagons. The four angles include 180 degree lines ("12:30"), 90 degree lines ("12:15"), 135 degree lines ("~12:22") and 45 degree lines ("~12:07"). Once a clock face is placed, the lines from it extend to connect to any other lines that surround it. Placing lines in such a way that it forms a shape - for example, placing four 90 degree clocks in such a way to form a square - earns the player points and removes the clocks used to form the shape. Larger shapes are more risky but earn more points. The player is given some leeway to recover from mistakes: should the player hold the down button to make a clock fall faster, it''ll destroy any clocks underneath. A misplacement, therefore, can be rectified with a correctly positioned clock if it falls quickly enough to crush the offending clock. However, the player can only do this a limited number of times per stage.' FROM games WHERE igdb_id = 41369 ON CONFLICT (game_id, language_code) DO NOTHING;
