INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crystal-caves-volume-3-milo-versus-the-supernova', 51392, '1991-11-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co63df.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crystal Caves Volume 3: Milo Versus the Supernova', 'Mylo Steamwitz, an enterprising space trader, has set out to the perilous mines of the Altairian system. He hopes to collect enough crystals to start a profitable twibble farm. Crystal Caves is a side-scrolling platform game, where the objective is to finish all 16 levels, collecting every single crystal within. On his way, Mylo is threatened by numerous monsters, such as bats, robots, mine carts or dinosaurs; there are also a lot of hazards such as stalactites and stalagmites, pipes which leak harmful water or poisonous mushrooms which kill instantly. Mylo has three health points, and if he is harmed enough times to deplete them all, he dies (but thankfully he has unlimited lives). To defend himself, Mylo has a missile pistol, which is able to take out most enemies, but not all. Many levels require the player to act fast and plan beforehand, as it''s easy to get Mylo stuck in an impossible-to-win situation - if this happens, the level must be restarted. Apart from the crystals, the levels contain a lot of items to collect: ammunition for the pistol, bonus items such as pickaxes or purple mushrooms that give score, and eggs which turn into letters when shot - collecting all 5 letters (B, O, N, U, S) on a level gives a lot of points, but it''s not always easy to get them! It''s also possible to find a power-up that reverses gravity when picked up, another one which gives your pistol the power to kill every enemy, a stop sign which freezes all enemies and makes them harmless and a red mushroom which allows you to kill enemies by running into them. These power-ups last only for a limited time though, so be careful, as they are always instrumental to victory!' FROM games WHERE igdb_id = 51392 ON CONFLICT (game_id, language_code) DO NOTHING;
