INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D Construction Kit', '3D Construction Kit (US, Canada and Israel release title: Virtual Reality Studio[3]), also known as 3D Virtual Studio, is a utility for creating 3D worlds in Freescape. Developed by Incentive Software and published by Domark, it was released in 1991 on multiple platforms. The game originally retailed for £24.99 for the 8-bit version, and £49.99 for 16-bit version, in the United Kingdom. A sequel, 3D Construction Kit II, was released in 1992, but only available on Amiga, Atari ST and MS-DOS.' FROM games WHERE igdb_id = 38852 ON CONFLICT (game_id, language_code) DO NOTHING;
