INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Pro Wrestling', 'Monster Pro Wrestling is a Japanese game in which you choose a monster and battle other monsters in turn-based battles. It is notable for its humorously nonsensical battle animations, such as the appearance of a dozen heads on screen and death blows literally tearing monsters apart.' FROM games WHERE igdb_id = 42069 ON CONFLICT (game_id, language_code) DO NOTHING;
