INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M-1 Abrams Battle Tank', 'Take the most powerful NATO tank, the M-1 Abrams, in 8 difficult missions against the Warsaw Pact forces. The four tank stations and the other aspects of the tank are quite nicely simulated, with different types of cannon rounds, coax machine guns, and all that. There''s also the independent turret and track rotation commands.' FROM games WHERE igdb_id = 45775 ON CONFLICT (game_id, language_code) DO NOTHING;
