INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyramid Magic II', 'Pyramid Magic II (ピラミッドマジックII) is a puzzle-platform game for the Sega Mega Drive, released exclusively in Japan via the Sega Game Toshokan service.  Pyramid Magic II claims to be a "sequel" to Pyramid Magic, though is more of a continuation of the original game, with identical graphics, sounds and gameplay. It even shows the Pyramid Magic levels on the map screen. The difference is that Pyramid Magic II offers harder levels.' FROM games WHERE igdb_id = 4374 ON CONFLICT (game_id, language_code) DO NOTHING;
