INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('amanda-stories', 262405, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6yra.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amanda Stories', 'Amanda Stories was the one of the very first "point-and-click" programs for kids. Not only is there a strong narrative--in ten separate stories Inigo explores his house, his dream, the outside world, and Your Faithful Camel ventures as far afield as the North Pole--but where you click actually determines the course of the story. As children (ages 3 and up) move intuitively through one adventure after another, the combination of color animations, great sound effects, original music, and a variety of endings challenges and delights them.' FROM games WHERE igdb_id = 262405 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 262405 AND ge.slug = 'point-and-click' ON CONFLICT DO NOTHING;
