INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Great Deal', 'Similar to poker, your deck consists of the four different suits with values from 2 to ace, plus one joker card, so 53 cards in total. You don''t hold them in your hand, though, but they fall down from the top of the screen into a play field 5 places wide and 5 places high, filling the bottom first. And your job is to arrange them into combinations such that they disappear and do not fill up the screen.' FROM games WHERE igdb_id = 267653 ON CONFLICT (game_id, language_code) DO NOTHING;
