INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where''s Waldo?', 'Your goal is to find Waldo in various pictures in order to progress through the game. The pictures are still images the size of the screen in the Easy and Practice levels. In the Medium and Hard levels, the player has to scroll to the side to see the rest of the area. The directional buttons control a magnifying glass and once the player finds Waldo, they get to go to the next level and a new picture.' FROM games WHERE igdb_id = 10618 ON CONFLICT (game_id, language_code) DO NOTHING;
