INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Personal Organizer and Phone Book', 'Get it all together with the Personal Organizer! A phone book, a day planner, and a calendar all in one. Store up to 90 names and phone numbers. Keep track of appointments and events with the built-in day planner, and find dates up until the year 2000 with the built-in calendar. Also featured is a complete listing of the most often used 800 numbers, a world clock with over 75 cities, a fully functioning calculator and a notepad.' FROM games WHERE igdb_id = 93538 ON CONFLICT (game_id, language_code) DO NOTHING;
