INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('builderland-the-story-of-melba', 13451, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/er9emeygsiaqyas8pwxj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qquofp9kmtbgh7v5ljnd.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Builderland: The Story of Melba', 'The story of this game is quite simple, presented during the intro as a series of short scenes without words. Melba is an easy-going guitar player who is having a picnic with his girlfriend; suddenly, an ultra-strong, evil-looking character appears and kidnaps the poor girl, sailing away on his ship. The brave Melba swims after the ship, and finds a bottle with a map inside. Knowing now the way to the evil kidnapper''s lair, Melba embarks on a journey without further hesitation! The premise, the map with the "stages", and the side-scrolling view indicate a platform-type action game; in reality, however, Builderland is a puzzle game, somewhat similar to the famous Lemmings. As in Lemmings, the player has no control over the protagonist himself (except on a few occasions, when "boss" enemies must be defeated by throwing certain objects at them). Instead, the player must manipulate the environment in order to build a path for Melba, deal with the enemies, etc. Melba is for the most part entirely helpless and simply walks forward automatically. Various items such as boxes, weapons, platforms, etc., must be collected and placed properly in order to save the hero from premature death.' FROM games WHERE igdb_id = 13451 ON CONFLICT (game_id, language_code) DO NOTHING;
