INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Mutant', 'Metal Mutant is a side-scrolling action-adventure game developed and published for MS-DOS, Amiga and Atari ST by Silmarils and released in 1991. It is similar to Game Arts'' Thexder in that it allows you to transform at any time into three different robot forms (Cyborg, Dino and Tank).' FROM games WHERE igdb_id = 10852 ON CONFLICT (game_id, language_code) DO NOTHING;
