INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Into Magicland', 'Into Magicland was a five-screen mini-adventure, which was given away with the January 1991 edition of Crash magazine in the UK. The player takes control of Dizzy''s cousin Danny and it a prequel to the main game, ending with Dizzy teleporting to the first screen of Magicland Dizzy. This was the only time Danny appeared in the Dizzy series.' FROM games WHERE igdb_id = 45342 ON CONFLICT (game_id, language_code) DO NOTHING;
