INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie PC Fashion Design & Color', 'Introducing a whole new world of fun! Now, you can enhance your child''s creative potential with the new Barbie PC Fashion Design & Color! It''s an explosion of fashion, color, and fun! This menu-driven software program lets your child select, then color Barbie fashions. Thousands of combinations to choose from for hours of fun. Available for IBM or IBM-compatible PCs in 3½ inch and 5¼ inch Disk versions.' FROM games WHERE igdb_id = 261889 ON CONFLICT (game_id, language_code) DO NOTHING;
