INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Cop', 'Cosmic Cop, known in Japan as Armed Police Unit Gallop, is a shooter arcade game developed and released by Irem in 1991, running upon the Irem M-84 arcade board. While not directly based on the R-Type series, it is considered a spin-off of such, with many features being adapted into later games, notably R-Type Final.' FROM games WHERE igdb_id = 94911 ON CONFLICT (game_id, language_code) DO NOTHING;
