INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dedant', 'Dedant is the fourty sixth game of the NES version of Action 52. You''re a pink ant who has to kill other ants. But in the later levels, if a spider gets down where you are, you''re pretty much screwed. The game has six levels. With each level, more types of enemies appear.' FROM games WHERE igdb_id = 245106 ON CONFLICT (game_id, language_code) DO NOTHING;
