INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gate', 'Gate is an action-adventure game for the Macintosh. It blends action, adventure, and brain-teasing challenges into an addictive fast-action game with smooth animation, exciting music and sound effects. Escape the castle''s prison, battle enemies, solve puzzles, and defeat your captor to restore peace to the land.' FROM games WHERE igdb_id = 170353 ON CONFLICT (game_id, language_code) DO NOTHING;
