INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokkyuu Shirei Solbrain', 'Tokkyuu Shirei Solbrain following the same storyline as the TV show of the same name, is a 2D action game where your main weapon is hand-to-hand combat. You can also intercept bullets with your attacks and there are power-ups as well along the way on every stage. The stages are devided into Areas, from A - G. Area B - F can be played in any ordere via a select screen and Area G will be open until all previous areas have been cleared.' FROM games WHERE igdb_id = 215134 ON CONFLICT (game_id, language_code) DO NOTHING;
