INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penthouse Electric Jigsaw', 'This adult version of Electric Jigsaw combines the engine of the original game with 12 pictures of Penthouse USA 1990 Pets of the Month. The jigsaw puzzle is proposed for a size from 6 pieces to 294 pieces. Unlike the original, there are no picture animation and music tune, when the puzzle is completed. High scores based on the puzzle size and time for its solution are stored for each picture.' FROM games WHERE igdb_id = 119301 ON CONFLICT (game_id, language_code) DO NOTHING;
