INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flash', 'The Flash is a game for the Game Boy, based on the 1990 television series of the same name. It was produced by THQ and released in the US in 1991. The box art for the game features John Wesley Shipp as The Flash, a man with the ability to run "faster than a speeding bullet." In daily life, The Flash becomes is a Crime Lab technician named Barry Allen.' FROM games WHERE igdb_id = 100289 ON CONFLICT (game_id, language_code) DO NOTHING;
