INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TradeWars 2002', 'Trade Wars 2002 is a classic BBS door game that has been actively played since the late 1980s. The player controls a spaceship in a Star Trek-inspired universe, trading resources at a profit to build up a space empire of planets and space stations. It was later adapted to play over the internet and external tools were built to automate repetitive tasks. The game is still playable on many web BBSes today.' FROM games WHERE igdb_id = 72576 ON CONFLICT (game_id, language_code) DO NOTHING;
