INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spanky''s Quest', 'Wicked witch turns fruits into monsters, Mopoland Population famished! Welcome to Mopoland, where the evil witch Morticia has cast an evil spell and turned all the fruits of the mighty kingdom into fiendish monsters. Spanky, our primate hero is on a quest. Armed with his magic ball, Spanky must hunt down Morticia through six grueling levels to liberate Mopoland, and save it’s citizens from a certain famine. -Fun, playful characters. -Password continue feature. -Unique traps and bonus rooms. -Fantasy/Adventure for the entire family.' FROM games WHERE igdb_id = 49017 ON CONFLICT (game_id, language_code) DO NOTHING;
