INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hyaku no Sekai no Monogatari: The Tales on a Watery Wilderness', 'This Famicom title by ASK combines the mechanics of a tabletop board game with the battle style and character progression of a role-playing game to create an interesting hybrid. One to two players can embark on a great adventure to explore the realm of Yukiria and complete quests for its inhabitants, with multiple endings possible!' FROM games WHERE igdb_id = 48124 ON CONFLICT (game_id, language_code) DO NOTHING;
