INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('7-colors', 11878, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/utymg2o7etu0u0ypbtzy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ghpbaxs2pcxwuyg4ybot.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '7 Colors', 'Seven Colors is an simple game of colors and strategy. It''s a 2 player game, but you can also play against the computer. As an added bonus for human vs human, you can connect to each other through a network. Unfortunately you can''t set the difficulty and the AI is surprisingly good. So you can expect to constantly get beaten until you really get a handle on the advanced strategy of the game. The goal of this game is quite simple, you need to cover 50% of the board with your captured colors. The board consists of small squares of 7 different colors. You can capture more color pieces by selecting a new color on each turn, then all neighbouring pieces of the new color immediately change color to the new one and become yours. Your field then changes color every turn and consumes more and more color pieces until one player get 50%.' FROM games WHERE igdb_id = 11878 ON CONFLICT (game_id, language_code) DO NOTHING;
