INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'HyperZone', 'Hyper Zone plays like a cross between a racing game and shooter. The object of the game is to navigate each level while shooting enemies and earning points, until finally an encounter with a boss ends each level. After enough points are acquired, the player earns an "extend" and his or her ship is upgraded in the next stage. The player''s ship can receive up to six upgrades.' FROM games WHERE igdb_id = 42608 ON CONFLICT (game_id, language_code) DO NOTHING;
