INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanafuda Yuukyou-den: Nagarebana Oryuu', 'Hanafuda Yuukyou-den: Nagarebana Oryuu is a logical game with elements of erotic images. Naturally, you will see them only after victory. Hanafuda is a style of Japanese playing cards used to play a variety of games. Hanafuda translates to ''flower cards''. The name also refers to some games played with the cards.' FROM games WHERE igdb_id = 267655 ON CONFLICT (game_id, language_code) DO NOTHING;
