INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tsuppari Wars', 'Tsuppari Wars is an action video game for the Family Computer. The object is to acquire all of the enemies'' territory and defeat the evil gang leaders. The gangsters fight without any weapons and the violence level is mild compared to later gang-related games. Its spiritual descendant is Grand Theft Auto: San Andreas due to its simulation of gang warfare.' FROM games WHERE igdb_id = 48384 ON CONFLICT (game_id, language_code) DO NOTHING;
