INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cry Baby', 'A game featured in Action 52. Try to get cry baby back to his crib, but be careful to avoid open electric sockets, poisons, and fire in the stove. There are things to help along the way such as cookies, lollipops, candy bars and pacifiers. If the baby meets any bad guys trying to kidnap him, he squeezes the bottle and shoots them.' FROM games WHERE igdb_id = 245087 ON CONFLICT (game_id, language_code) DO NOTHING;
