INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s TaleSpin', 'TaleSpin is a video game for the TurboGrafx-16 console based on the animated series of the same name. It was designed by Interactive Designs and Radiance Software. It was published by Turbo Technologies Inc. in 1991. The TurboGrafx version is also a platform game, in which players play as Baloo. There is also a bonus level where players control the plane pulling Kit behind him.' FROM games WHERE igdb_id = 145182 ON CONFLICT (game_id, language_code) DO NOTHING;
