INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('los-templos-sagrados', 93266, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mxl.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Los Templos Sagrados', '"Los Templos Sagrados" is the second part of the adventure tritogy "LEGENDS OF CI-U-THAN" that covers a period and a fairly extensive area of ​​the geohistory of Yucatán.  The CI-U-THAN epic consists of three totally independent books and, therefore, such an extensive project has had to be developed in three complete games of several parts each.  The first book, divided into two parts, narrated your adventures from the arrival on the island of Cozumel as a poor and helpless castaway, until your triumphant departure from it.  In this second book, "LOS TEMPLOS SAGRADOS", you will have to find Chichén ltzá through the ruins of Cobá and Tulum.  The third book, "THE MYSTERY OF CHICHEN ITZA", will tell us about the fabulous final outcome in the most famous Mayan temple: Chichén ltzá.  So, now you have the opportunity to continue with the story of the famous adventurer and archaeologist Doc Monro in the lands of the archaic Mayan culture.' FROM games WHERE igdb_id = 93266 ON CONFLICT (game_id, language_code) DO NOTHING;
