INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Racer', 'Power Racer is a conversion of the arcade game Head On to the Game Boy that includes an extra special mode with multiplayer. Viewed from a top down perspective, the player has to race around a circuit consisting of five lanes and collect all the dots that lies scattered around. This mode features ten difficulty levels. The special mode has items and obstacles to face. You can also play in the special mode against a second human player.' FROM games WHERE igdb_id = 49088 ON CONFLICT (game_id, language_code) DO NOTHING;
