INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeta', 'Zeta is an adventure game with light dungeon crawling elements. The star ship Pilgrims is sent to investigate an accident on the planet Z (or Zeta-3) in the Zeta star system, and find out what happened to the first investigation team sent earlier, and to search for the lost transport ship Sanctuary.' FROM games WHERE igdb_id = 250525 ON CONFLICT (game_id, language_code) DO NOTHING;
