INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Slots', 'This is a simple slot machine simulation. What makes it different are the erotic pictures of naked or half-naked girls, which you get if you successfully complete a casino round and win a lot of money. There are three casinos you can play in, each one leading to different girls and different short scenes and comments from them.' FROM games WHERE igdb_id = 78980 ON CONFLICT (game_id, language_code) DO NOTHING;
