INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tut''s Tomb', 'Tut''s Tomb is a variation on "Pyramid", a patience or solitaire game of the Simple Addition family, where the object is to get all the cards from the pyramid to the foundation. The object of the game is to remove pairs of cards that add up to a total of 13, the equivalent of the highest valued card in the deck, from a pyramid arrangement of 28 cards. When using the standard 52-card deck, Jacks are valued at 11, Queens at 12, and Kings at 13.' FROM games WHERE igdb_id = 282107 ON CONFLICT (game_id, language_code) DO NOTHING;
