INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fascination', 'Fascination is an adventure game. It''s about a business man who has invented a chemical drug that increases the sex-drive. Unfortunately he was assassinated, and you accidentally get hold of the drug sample. Your mission is to try to deliver the sample to the right person and avoid being made out as the murderer.' FROM games WHERE igdb_id = 10793 ON CONFLICT (game_id, language_code) DO NOTHING;
