INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A.J.''s World of Discovery', 'A.J''s World of Discovery is an educational game aimed at young kids. It allows them to play various mini games such as an Arknanoid clone, a picture editor, sticker book, Matchbox car racing, jigsaw puzzles etc etc. A fun way to learn English and Maths.' FROM games WHERE igdb_id = 73176 ON CONFLICT (game_id, language_code) DO NOTHING;
