INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wing-commander-ii-deluxe-edition', 51373, '1991-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wvb.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wing Commander II: Deluxe Edition', 'Ten years ago, you were the Hero of Vega Sector, idol of millions - the starfighter pilot who single-handedly turned the tide of a major Kilrathi invasion. Then something went wrong. You were disgraced, court-martialed and transferred to a backwater outpost. For years, your lightning-quick reflexes and instinctive dogfighting tactics went to waste while the Kilrathi killed your closest friends on the front lines. But Mankind still needs a hero, now more than ever before. And you''re still the best pilot in the Galaxy. You''ve got just one chance to prove yourself, just one chance to keep the Terran homeworlds from falling to the massed armada of the Empire of Kilrah. Thank you can handle it, flyboy?' FROM games WHERE igdb_id = 51373 ON CONFLICT (game_id, language_code) DO NOTHING;
