INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Mech: Man & Machine', 'It can save mankind, but beware... this machine has a mind of its own! Welcome to the all-terrain attack vehicle of the future. It''s what you need in a world gone to the dogs! You can beat ''em into the ground, or blast ''em underground, or fight ''em alone!' FROM games WHERE igdb_id = 48082 ON CONFLICT (game_id, language_code) DO NOTHING;
