INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blue-almanac', 45645, '1991-07-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dc9yjy6ngtdckkmwrsib.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blue Almanac', 'Blue Almanac is a 1991 RPG for the Sega Mega Drive by HOT-B published by Kodansha Research Institute for some reason. While it was only released in Japan, Kodansha was planning on translating the game as Star Odyssey, but the translation was cancelled for unknown reasons. Two prototypes were independently discovered by drx and by Brandon Cobb, head of Super Fighter Team, who subsequently acquired a license to complete the translation from HOT-B successor company Starfish (who like to revisit old properties), with intentions on releasing it on the twentieth anniversary of the original release. Despite his PR claiming that he received an "unofficial license" from Sega to distribute the game, Sega really asked him to remove their copyrights and trademarks, consequently making the translation fully unlicensed (while Blue Almanac is fully licensed).' FROM games WHERE igdb_id = 45645 ON CONFLICT (game_id, language_code) DO NOTHING;
