INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Best Keiba Derby Stallion', 'Best Keiba Derby Stallion ("Best Race Derby Stallion") is a simulation game where the player has a stable and starting money and must raise champion racehorses. As well as training horses, they can breed them and, eventually, sell them once they grow too old to race. The player can also hire jockeys to ride their horses for races, and can gamble on races to earn a little extra funds. Best Keiba Derby Stallion began a long-running Derby Stallion franchise that persists to the present. It was only released in Japan.' FROM games WHERE igdb_id = 48724 ON CONFLICT (game_id, language_code) DO NOTHING;
