INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block Block', 'A ball travels across the screen, bouncing off the top and side walls of the screen. When a brick is hit, the ball bounces away and the brick is destroyed. The player loses a turn when the ball touches the bottom of the screen. To prevent this from happening, the player has a movable paddle to bounce the ball upward and back into play.' FROM games WHERE igdb_id = 46763 ON CONFLICT (game_id, language_code) DO NOTHING;
