INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gimme a Break: Shijou Saikyou no Quiz-ou Ketteisen', 'Gimme a Break: Shijou Saikyou no Quiz-ou Ketteisen is a quiz game released for the Famicom (NES) in Japan, and is based on an actual Japanese game show that aired from 1989 to 1992. Players can answer trivia questions against AI or human opponents, with the ultimate goal of challenging the game''s Quiz King.' FROM games WHERE igdb_id = 267651 ON CONFLICT (game_id, language_code) DO NOTHING;
