INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('can-can-bunny-spirits', 108894, '1991-08-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kw4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsp5h.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Can Can Bunny Spirits', 'The third in the Can Can Bunny series, Can Can Bunny Spirits deals with a nameless hero (the player has to give him a name) who is - in accordance with Can Can Bunny tradition - a lonely guy who can''t get a girlfriend. One night he sits at home and stares at the moon. Suddenly, the magic fairy Ariko appears in front of him and gives him... no, this time not the Magic Book, but a Magic Crescent! With the help of this crescent, the hero can turn into totally different young men - which will naturally increase his chances in impressing girls and ultimately having sex with them. Can Can Bunny Spirits is much less of an adventure and more of a strategy game than its predecessors. Success depends even more on the preparations before the actual decisive stage. There is also extensive customization in this game. In the beginning, the hero chooses what he wants to be like, which includes age, height, blood type, and other parameters. Then Ariko introduces several girls to him, of which he has to choose one. Afterwards, it''s a matter of asking the right questions and giving the right answers, combining knowledge of the girl''s preferences and of the character''s statistics. Each girl has a "love meter that can be raised or lowered depending on the player''s strategies, and once it is full, the hero can have his way with the girl.' FROM games WHERE igdb_id = 108894 ON CONFLICT (game_id, language_code) DO NOTHING;
