INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('strato-fighter', 41090, '1991-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r3c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scwmym.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Strato Fighter', 'Strato Fighter, otherwise known as Raiga: Strato Fighter, is a 1991 video arcade game developed by Tecmo. It is a horizontal side-scrolling space shooter in which two players may play simultaneously. The game sets players in the year 2135 on a mission to save the Earth from colony-based, militant alien invaders using the MB-OG Raiga (Thunder Fang). The Raiga has the ability to spin around to attack enemies from behind. Power-ups can be obtained by destroying container ships. The craft''s weapons include the Shotgun, Ion launcher, Vertical, Homing Missiles and Bomb attacks along with items such as Speed Ups, Shields and Extends. The spacecraft can also obtain an Option weapon called the Auto Guard; three types of Auto Guards were available such as the target locking Beam Rifle, the powerful Solid Shooter and the standard Blaster item.' FROM games WHERE igdb_id = 41090 ON CONFLICT (game_id, language_code) DO NOTHING;
