INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Force', 'Turbo Force is even more of a direct predecessor to Sonic Wings than is Rabio Lepus: Turbo Force. The story is that an American Air Force pilot, while racing his car on a public road, wanders into another mysterious dimension and gets caught up in a war there.' FROM games WHERE igdb_id = 39885 ON CONFLICT (game_id, language_code) DO NOTHING;
