INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('provocator', 37223, '1991-06-17', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Provocator', 'You play the role of the last fighter pilot remaining and must protect a convoy of HUGE spaceships from 32 waves of attacking aliens.  Several ships in the convoy have forest domes that supply the fleet with food and oxygen. The player is tasked with protecting these domes from alien squadrons that launch increasingly frequent attacks on them. When a dome is under attack, a warning sound alerts the player to the threat and if it isn''t met within 15 seconds, the dome is permanently destroyed. If all the forest domes are destroyed, the fate of the convoy is sealed and the game ends.  The game grants the player freedom to move around the convoy at will, but collision with any part of the fleet results in the loss of a life. Familiarity with the convoy layout is paramount to protecting it. Upon completion of a level the player is instructed to carefully dock with the largest ship in the fleet to re-fuel. Once successfully docked, bonus points are awarded for every dome left intact.  A radar at the top of the screen shows the fleet in its entirety, allowing the player to track alien movement and help navigate.  The game''s 32 levels are split into 3 acts (or ''phases'') Once a phase has been completed, the player is rewarded with a still postcard style snapshot of a ship in the fleet.' FROM games WHERE igdb_id = 37223 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 37223 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 37223 AND p.igdb_id = 116 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animac', 145243, '1991-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3gwx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc96z5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ANIMAC', '23rd-century Earth is a good place to be: after an atypically friendly first contact with an alien species, the planet''s ills have been cured and peace reigns supreme. But some will always resist change, let alone utopian ideas. One such organization was the innocently-named American Neutral Investigators, and its leader Mapier was exiled off-planet for disturbing the peace. This decision did not prove far-sighted however; Mapier worked diligently, pirating and destroying, harvesting debris, alien technology and raw materials, and gradually built up a huge armed space fortress from which the ANI continue to terrorize known space. This is where the player comes in, piloting an infiltrator ship into the bowels of the ANI''s Mapierian Anti-Complex (ANIMAC) to find and destroy the central command. The meandering tunnels burrowing through the planet-sized base consist of hundreds of different rooms, littered with automated defenses, mines and hostile drones, while the Infiltrator only packs a single forward-firing photon launcher. Bridges and invisible warps complicate matters further, as does the security system which makes backtracking a deadly risk.' FROM games WHERE igdb_id = 145243 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 145243 AND ge.slug = 'shooter' ON CONFLICT DO NOTHING;
