INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hunter', 'Hunter is a 3D action-adventure game in which the player navigates around a series of islands. Hunter was developed by Paul Holmes and Martin Walker (music), and it was released by Activision for the Amiga and Atari ST home computers in 1991. The combination of the game''s 3D graphics and sandbox-type gameplay has been subsequently compared to the Grand Theft Auto series and similar sandbox games, such as Far Cry 2.' FROM games WHERE igdb_id = 12149 ON CONFLICT (game_id, language_code) DO NOTHING;
