INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrath of the Demon', 'Wrath of the Demon is a computer game developed by a Quebec-based team called Abstrax. Versions for Atari ST, Amiga, Commodore CDTV, PC and Mac were released in Early 1991. There was also a Commodore 64 version.  The player controls a hero on a quest to defeat a demon. Gameplay styles include hack ''n'' slash (combat at close quarters), horse riding, etc.' FROM games WHERE igdb_id = 12832 ON CONFLICT (game_id, language_code) DO NOTHING;
