INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super High Impact', 'Super High Impact was one of the most hard hitting football games before the NFL Blitz series was created, with 18 teams and over 30 plays per team. The console versions are based on the Midway arcade series of the same name. The game has a Hit-O-Meter which often leads to massive brawls. Based on the arcade smash hit back in the days, featuring the three famous words: EAT THIS!!!, FIGHT!!!' FROM games WHERE igdb_id = 38417 ON CONFLICT (game_id, language_code) DO NOTHING;
