INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Hornet', 'This Hi-Tec Mega game puts a highly advanced and extremely will equipped aircraft at your disposal. At your disposal is a range of air-to-air and air-to-ground weapons with which you can destroy the might of the enemy forces, its aircraft, ships and ground installations. All your skill at the controls will be needed, moving Black Hornet in three dimensions, to avoid or destroy enemies and missiles, whilst ensuring that the aircraft does not collide with the terrain.' FROM games WHERE igdb_id = 14309 ON CONFLICT (game_id, language_code) DO NOTHING;
