INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wacky Races', 'You take on the role of Dastardly and Mutley from the Hanna-Barbera cartoon series in this action title with superficial racing overtones. Your aim is to complete each course in a particular position, which is achieved either by waiting for them to suffer enough damage to drop out of the race, or by inflicting that damage yourself. Your car is armed with a forward-shooting arrow to impale the opposition cars, and deal with the many hazards the races throw at you, including boulders and rabbits, which can be taken out for points.' FROM games WHERE igdb_id = 12817 ON CONFLICT (game_id, language_code) DO NOTHING;
