INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doki! Doki! Yuuenchi: Crazy Land Daisakusen', 'Doki! Doki! Yuuenchi: Crazy Land Daisakusen is a Nintendo Family Computer video game developed by KID and released in 1991 by VAP. Players control a boy with a helmet who kicks balls at enemies in an attempt to save his girlfriend from an unknown force inside an amusement park. The more damage he takes the more damage he does to enemies. The game was renamed The Trolls in Crazyland for release on the NES by American Softworks. It was previously scheduled to be released as Crazyland, but was then changed to feature the popular Troll dolls. That version was only released in Italy(PAL-A), and Eastern Europe(PAL-B).' FROM games WHERE igdb_id = 48663 ON CONFLICT (game_id, language_code) DO NOTHING;
