INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GG Aleste', 'GG Aleste is a game in Compile''s Aleste series of shoot-''em-ups for the Sega Game Gear. It was only released in Japan and is one of the few Compile Game Gear games published by Compile rather than Sega.' FROM games WHERE igdb_id = 46317 ON CONFLICT (game_id, language_code) DO NOTHING;
