INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ganbare Goemon: Sarawareta Ebisumaru!', 'Originally released as Ganbare Goemon: Sarawareta Ebisumaru!, it is a Game Boy game released in 1991 and the first game in the Goemon series ever released for a portable system. Gameplay is similar to Ganbare Goemon! Karakuri Douchuu which was released on the Famicom. Only Goemon is playable, and the game consists of him rescuing Ebisumaru; Sasuke and Yae do not make appearances.' FROM games WHERE igdb_id = 62493 ON CONFLICT (game_id, language_code) DO NOTHING;
