INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Extreme', 'Extreme is a fast-paced action game for the ZX Spectrum that pits players against alien pirates across three diverse environments. Players navigate through space, underwater, and a building interior, each section offering unique gameplay mechanics and challenges. Despite its modest origins as a spare-time project, the game boasts impressive graphics and special effects for its platform. The compact adventure can be completed in about 20 minutes, delivering an intense, varied experience that showcases the Spectrum''s capabilities.' FROM games WHERE igdb_id = 13655 ON CONFLICT (game_id, language_code) DO NOTHING;
